DEFAULT_REFERENCE_SIGNAL_PATH = os.path.normpath(
        os.path.join(
            os.path.dirname(__file__),
            '../dascalibration/resources/calibration_tone_long_s32le.wav'))

logging.basicConfig(format='%(levelname)s: %(message)s', level=logging.INFO)


def read_reference_signal(path = DEFAULT_REFERENCE_SIGNAL_PATH):
    """Reads the reference signal from disk, returning the raw buffer data."""
    with wave.open(path, 'rb') as f:
        assert (f.getnchannels() == 1), 'Expected a single channel stimulus signal.'
        assert (f.getframerate() == 48e3), 'Expected a 48kHz stimulus signal.'
        logging.debug(f'Reading reference signal. Params: {f.getparams()}')
        raw = f.readframes(f.getnframes())
        buf = numpy.frombuffer(raw, dtype=numpy.int32).astype(numpy.float64) / 2**31
        return buf

def schedule(head, calibration_id, sample_time, duration, proxy, i):
    """Schedule the given cell for playback and/or recording. The head denotes
       the index of the cell who should chirp for any given round of the schedule,
       while i denotes the cell index being scheduled currently."""
    if i == head:
        logging.info(f'Scheduling {proxy} to chirp and record at {sample_time}')
        return proxy.capture_and_play(calibration_id, sample_time, duration)

    logging.info(f'Scheduling {proxy} to just record at {sample_time}')
    return proxy.capture(calibration_id, sample_time, duration)

async def analyze_tof_and_aoa(calibration_id, proxy, target_ip, file_path, target_serial):
    """Asks a given cell to analyze the recording at the given file path.

    This will prompt a TOF (time of flight) and AOA (angle of arrival) calculation
    on the remote cell, and return a [tof, aoa] pair of float numbers."""

    logging.info(f'Kicking off {proxy} for ToF/AoA analysis')
    loop = asyncio.get_running_loop()
    return await loop.run_in_executor(None, proxy.estimate_tof_and_aoa, calibration_id, target_ip, file_path, target_serial)

async def estimate_roomeq(calibration_id, proxy, file_path):
    """Asks a given cell to analyze the recording at the given file path.

    This will prompt a roomeq calculation on the remote cell, and return a
    set of filter coefficients [[freq, gain, q], ...]."""
    logging.info(f'Kicking off {proxy} for RoomEQ analysis')
    loop = asyncio.get_running_loop()

    walls = await loop.run_in_executor(None, proxy.evaluate_room_eq, calibration_id, file_path)
    return json.loads(walls)

async def estimate_mc_roomeq(calibration_id, proxy, file_path, tf_matrix, cell):
    """Asks a given cell to analyze the recording at the given file path.

    This will prompt a mcroomeq calculation on the remote cell, and return a
    set of filter coefficients [[freq, gain, q], ...]."""
    logging.info(f'Kicking off {proxy} for McRoomEQ analysis')
    loop = asyncio.get_running_loop()

    walls = await loop.run_in_executor(None, proxy.evaluate_mc_room_eq, calibration_id, file_path, tf_matrix, cell)
    return json.loads(walls)

async def estimate_physical_layout(proxy, calibration_id, tof_aoa_matrix):
    """Computes a physical layout estimation on the local cell given a
       matrix of tof/aoa values."""

    tof_matrix = [[a[0] for a in b] for b in tof_aoa_matrix]
    aoa_matrix = [[a[1] for a in b] for b in tof_aoa_matrix]
    height_matrix = [[float(a[2]) for a in b] for b in tof_aoa_matrix]

    loop = asyncio.get_running_loop()
    return await loop.run_in_executor(None, proxy.estimate_physical_layout, calibration_id, tof_matrix, aoa_matrix, height_matrix)

async def send_measurement_matrix_to_secondaries(proxy, target_ip, matrix, i_am_cell):
    """Sends a given cell the matrix of measurements for McRoomEQ"""

    logging.info(f'Kicking off {proxy} for McRoomEQ')
    loop = asyncio.get_running_loop()
    return await loop.run_in_executor(None, proxy.send_matrix, target_ip, matrix, i_am_cell)

async def estimare_rir(calibration_id, proxy, target_ip, file_path, target_serial):
    """Asks a given cell to analyze the recording at the given file path."""
    loop = asyncio.get_running_loop()
    return await loop.run_in_executor(None, proxy.estimate_rir, calibration_id, target_ip, file_path, target_serial)


async def round_robin(calibration_id, proxies, stimulus_filepath, signal_duration, playback_gain):
    """Runs the round robin measurement step for each Cell to which we have a proxy."""
    try:
        # Then, prepare each cell
        start = time.time()
        ready = all([p.prepare(stimulus_filepath, playback_gain) for p in proxies])
        logging.info(f'Prepare took {numpy.round(time.time() - start, 2)}s')
        if not ready:
            raise RuntimeError('Failed to prepare all of our cells')

        # Now we can run the round robin scheduling. We will run N iterations for N
        # Cells where for each iteration we collect N wav files representing what each
        # Cell recorded during that iteration.
        #
        # With that, we assemble a square matrix of file paths. When the round robin
        # is over, we process the recorded files matrix to determine Room EQ coefficients,
        # and a physical layout estimation.
        capture_time_client = syngnative.CaptureTimeClient()
        num_cells = len(proxies)
        round_robin_start = time.time()
        results_matrix = []

        for i in range(num_cells):
            sample_time = capture_time_client.get_capture_time()
            scheduler = functools.partial(schedule, i, calibration_id, sample_time + 48000, signal_duration + 48000)

            start = time.time()
            row_results = await asyncio.gather(*map(scheduler, proxies, range(num_cells)))

            if not all(row_results):
                none_indices = [i for i, x in enumerate(row_results) if x is None]
                cell_error_string = 'Following cells had a problem: '
                for idx in none_indices:
                    cell_error_string += f'{proxies[idx]}, '
                raise RuntimeError(f'One of the clients hit an underrun during calibration. {cell_error_string}')

            results_matrix.append(row_results)
            logging.info(f'Round robin step took {numpy.round(time.time() - start, 2)}s')

        # Now after that, we have a matrix of file paths indicating what each cell
        # heard at what step.
        logging.info(f'Complete round robin process took {numpy.round(time.time() - round_robin_start, 2)}s')
        logging.debug(f'Recorded files: {results_matrix}')

        return results_matrix
    finally:
        # Finally, mark them all done
        for p in proxies:
            p.done()

async def calibrate(calibration_id, cells, reference_signal_path=DEFAULT_REFERENCE_SIGNAL_PATH):
    """Here calibration_id is as expected, and cells just a list of dictionaries,
       where each dictionary holds the cell_id and the cell_ip."""
    num_cells = len(cells)

    if num_cells < 1:
        logging.error('Cannot calibrate without cell')
        return None

    logging.info(f'Calibration ID: {calibration_id}')
    # Establish our proxies
    proxies = [syngnative.CalibrationClientProxy(cell['serial_number'], cell['ip_address']) for cell in cells]
    analysis_proxies = [syngnative.CalibrationAnalysisProxy(cell['serial_number'], cell['ip_address']) for cell in cells]

    try:
        await asyncio.gather(*map(prepare, analysis_proxies))

        # First up we read the reference signal off disk
        reference_signal = read_reference_signal(reference_signal_path)

        # get the long term noise level, playback stimulus +6dB louder if we are above a threshold
        long_term_rms_micsignal = proxies[0].get_long_term_room_noise_rms()

        logging.info(f'Long Term RMS microphone level: {long_term_rms_micsignal}dBSPL')

        THRESHOLD_FOR_LOUDER_STIMULUS = 65
        playback_gain = 1.0 if long_term_rms_micsignal <= THRESHOLD_FOR_LOUDER_STIMULUS else 2.0

        if long_term_rms_micsignal > THRESHOLD_FOR_LOUDER_STIMULUS:
            logging.info(f'High noisefloor detected, will measure 6dB louder.')

        # Measure the cells
        results_matrix = await round_robin(calibration_id, proxies, reference_signal_path, len(reference_signal), playback_gain)

        # If we're the only cell, we can run RoomEQ and stop after that
        if num_cells == 1:
            start = time.time()
            roomeq_analyzer = functools.partial(estimate_roomeq, calibration_id)
            self_recordings = numpy.array(results_matrix).diagonal()
            walls = await asyncio.gather(*map(roomeq_analyzer, analysis_proxies, self_recordings))
            logging.info(f'Calculating roomeq and wall detection step took {numpy.round(time.time() - start, 2)}s')

            result = [{
                'serial_number': c['serial_number'],
                'nearby_walls': w,
            } for c, w in zip(cells, walls)]

            calibration_put_result = await cloudapi.put_calibration_results(result)
            logging.info(f'PUT Request: {calibration_put_result}')
            return None

        # Else we move ahead to running physical layout estimation, kicking off
        # with the ToF/AoA calculation
        start = time.time()

        analyzer = functools.partial(analyze_tof_and_aoa, calibration_id)
        tof_aoa_matrix = []

        for i, row_results in enumerate(results_matrix):
            target_ip = cells[i]['ip_address']
            target_serial = cells[i]['serial_number']
            tof_aoa_matrix.append(await asyncio.gather(*map(analyzer, analysis_proxies, [target_ip] * num_cells, row_results, [target_serial] * num_cells)))

        logging.info(f'Calculating AOA/TOF took {numpy.round(time.time() - start, 2)}s')
        ple_results = await estimate_physical_layout(analysis_proxies[0], calibration_id, tof_aoa_matrix)
        [positions, rs] = ple_results
        # Troubadour: keep the raw measurement matrices so the agent can combine several runs robustly
        try:
            import json as _json, os as _os
            _os.makedirs('/data/syng-agent', exist_ok=True)
            with open('/data/syng-agent/calib-matrices.jsonl', 'a') as _f:
                _f.write(_json.dumps({'t': time.time(), 'calibration_id': calibration_id, 'noise_dbspl': long_term_rms_micsignal,
                                      'cells': [c['serial_number'] for c in cells],
                                      'tof': [[float(a[0]) for a in b] for b in tof_aoa_matrix],
                                      'aoa': [[float(a[1]) for a in b] for b in tof_aoa_matrix],
                                      'upside': [[int(a[2]) for a in b] for b in tof_aoa_matrix],
                                      'positions': positions, 'rotations': rs}) + '\n')
        except Exception as _e:
            logging.error(f'Troubadour matrix dump failed: {_e}')
        logging.info(f'Calculating full PLE took {numpy.round(time.time() - start, 2)}s')
        logging.debug(f'Positions: {positions}')
        logging.debug(f'Rotations: {rs}')

        start = time.time()
        mc_roomeq_analyzer = functools.partial(estimate_mc_roomeq, calibration_id)
        self_recordings = numpy.array(results_matrix).diagonal()
        mc_room_eq_matrix = [[a[3] for a in b] for b in tof_aoa_matrix]

        walls = await asyncio.gather(*map(mc_roomeq_analyzer, analysis_proxies, self_recordings, [mc_room_eq_matrix] * num_cells, [i for i in range(num_cells)]))
        logging.debug(f'walls: {walls}')
        logging.info(f'Calculating mc roomeq and wall detection step took {numpy.round(time.time() - start, 2)}s')


        result = [{
            'serial_number': c['serial_number'],
            'nearby_walls': w,
            'position': {
                'x': p[0],
                'y': p[1],
                'z': p[2],
                'rotation': r,
            }
        } for c, w, p, r in zip(cells, walls, positions, rs)]

        calibration_put_result = await cloudapi.put_calibration_results(result)
        logging.info(f'PUT Request: {calibration_put_result}')
    finally:
        await asyncio.gather(*map(cleanup, analysis_proxies))

async def prepare(proxy):
    logging.info(f'Kicking off {proxy} for Prepare')
    await asyncio.get_running_loop().run_in_executor(None, proxy.prepare)

async def cleanup(proxy):
    logging.info(f'Kicking off {proxy} for Cleanup')
    await asyncio.get_running_loop().run_in_executor(None, proxy.cleanup)

async def measure(calibration_id, cells, reference_signal_path=DEFAULT_REFERENCE_SIGNAL_PATH):
    """Here calibration_id is as expected, and cells just a list of dictionaries,
       where each dictionary holds the cell_id and the cell_ip.

       Measure will stop after measuring each cell and return the resulting recorded files
       matrix. If you want to run the full analysis, see `calibrate`."""
    # First up we read the reference signal off disk
    reference_signal = read_reference_signal(reference_signal_path)

    # Establish our proxies
    proxies = [syngnative.CalibrationClientProxy(cell['serial_number'], cell['ip_address']) for cell in cells]
    analysis_proxies = [syngnative.CalibrationAnalysisProxy(cell['serial_number'], cell['ip_address']) for cell in cells]

    # Measure the cells
    results_matrix = await round_robin(calibration_id, proxies, reference_signal_path, len(reference_signal), 1.0)

    analyzer = functools.partial(estimare_rir, calibration_id)

    num_cells = len(cells)

    for i, row_results in enumerate(results_matrix):
        target_ip = cells[i]['ip_address']
        target_serial = cells[i]['serial_number']
        await asyncio.gather(*map(analyzer, analysis_proxies, [target_ip] * num_cells, row_results, [target_serial] * num_cells))

    return None
